// Package ast rewrites struct tags of Go code generated by protoc-gen-go, by field_tag options and
// @gotags comments of fields.
package ast

import (
	"bytes"
	"fmt"
	"go/ast"
	"go/format"
	"go/parser"
	"go/token"
	"slices"
	"strings"

	"google.golang.org/protobuf/compiler/protogen"
	"google.golang.org/protobuf/proto"
	"google.golang.org/protobuf/types/descriptorpb"

	"github.com/searKing/golang/go/reflect"
	strings_ "github.com/searKing/golang/go/strings"

	pb "github.com/searKing/golang/tools/protoc-gen-go-tag/tag"
)

const generatedComment = "// Code generated by protoc-gen-go-tag. DO NOT EDIT.\n"

// reservedTagKeys are struct tag keys the protobuf runtime relies on, which field_tag must not set.
var reservedTagKeys = []string{"protobuf", "protobuf_oneof"}

// Comment directives of struct tags, written in a line of leading or trailing comments of a field,
// such as:
//
//	// @gotags: validate:"required" json:"name"
const (
	updateDirective  = "@gotags:"
	replaceDirective = "@gotags-replace:"
)

// fieldTag is a struct tag of a field, set by a field_tag option or a comment directive.
type fieldTag struct {
	tag            *reflect.StructTag
	updateStrategy pb.FieldTag_UpdateStrategy
}

// structTags maps names of Go structs to names of their fields to struct tags, applied in order.
type structTags map[string]map[string][]fieldTag

// Rewrite rewrites struct tags in g, the Go code generated by protoc-gen-go for file, by field_tag options and
// @gotags comments of fields, replacing g by a new generated file of the same name.
// Struct and field names are the ones generated by protogen, so that renamed ones are matched,
// such as Reset_ of the field reset.
func Rewrite(gen *protogen.Plugin, file *protogen.File, g *protogen.GeneratedFile) error {
	tags, err := fileStructTags(file)
	if err != nil {
		return err
	}
	if len(tags) == 0 {
		return nil
	}
	content, err := g.Content()
	if err != nil {
		return err
	}
	content, err = rewriteContent(content, tags)
	if err != nil {
		return fmt.Errorf("%s: %w", file.Desc.Path(), err)
	}
	g.Skip()
	_, err = gen.NewGeneratedFile(file.GeneratedFilenamePrefix+".pb.go", file.GoImportPath).Write(content)
	return err
}

// fileStructTags returns struct tags of fields of messages in file, by Go names of their structs and fields.
func fileStructTags(file *protogen.File) (structTags, error) {
	tags := structTags{}
	var walk func(messages []*protogen.Message) error
	walk = func(messages []*protogen.Message) error {
		for _, message := range messages {
			for _, field := range message.Fields {
				fieldTags, err := fieldTagsOf(field)
				if err != nil {
					return err
				}
				if len(fieldTags) == 0 {
					continue
				}
				// A field of a oneof is generated in a wrapper struct, rather than the struct of the message,
				// except for proto3 optional fields, whose oneofs are synthetic.
				structName := message.GoIdent.GoName
				if field.Oneof != nil && !field.Oneof.Desc.IsSynthetic() {
					structName = field.GoIdent.GoName
				}
				if tags[structName] == nil {
					tags[structName] = map[string][]fieldTag{}
				}
				tags[structName][field.GoName] = fieldTags
			}
			if err := walk(message.Messages); err != nil {
				return err
			}
		}
		return nil
	}
	if err := walk(file.Messages); err != nil {
		return nil, err
	}
	return tags, nil
}

// fieldTagsOf returns struct tags of field, by the field_tag option, then comment directives in leading comments,
// then in trailing comments.
func fieldTagsOf(field *protogen.Field) ([]fieldTag, error) {
	var tags []fieldTag
	add := func(source, structTag string, strategy pb.FieldTag_UpdateStrategy) error {
		tag, err := parseFieldTag(structTag, strategy)
		if err != nil {
			return fmt.Errorf("%s: %s: %w", field.Desc.FullName(), source, err)
		}
		tags = append(tags, tag)
		return nil
	}

	opts, _ := field.Desc.Options().(*descriptorpb.FieldOptions)
	if opts != nil && proto.HasExtension(opts, pb.E_FieldTag) {
		v := proto.GetExtension(opts, pb.E_FieldTag).(*pb.FieldTag)
		if err := add("field_tag", v.GetStructTag(), v.GetUpdateStrategy()); err != nil {
			return nil, err
		}
	}
	for _, comments := range []protogen.Comments{field.Comments.Leading, field.Comments.Trailing} {
		for line := range strings.Lines(string(comments)) {
			line = strings.TrimSpace(line)
			for _, d := range []struct {
				directive string
				strategy  pb.FieldTag_UpdateStrategy
			}{
				{replaceDirective, pb.FieldTag_replace},
				{updateDirective, pb.FieldTag_update},
			} {
				structTag, ok := strings.CutPrefix(line, d.directive)
				if !ok {
					continue
				}
				if err := add(strings.TrimSuffix(d.directive, ":"), strings.TrimSpace(structTag), d.strategy); err != nil {
					return nil, err
				}
				break
			}
		}
	}
	return tags, nil
}

// parseFieldTag parses structTag, which must not set struct tags the protobuf runtime relies on.
func parseFieldTag(structTag string, strategy pb.FieldTag_UpdateStrategy) (fieldTag, error) {
	tag, err := reflect.ParseStructTag(structTag)
	if err != nil {
		return fieldTag{}, fmt.Errorf("malformed struct tag %q: %w", structTag, err)
	}
	for _, t := range tag.Tags() {
		if slices.Contains(reservedTagKeys, t.Key) {
			return fieldTag{}, fmt.Errorf("must not set struct tag %q, which the protobuf runtime relies on", t.Key)
		}
	}
	return fieldTag{tag: tag, updateStrategy: strategy}, nil
}

// rewriteContent rewrites struct tags of fields in the Go source content by tags.
func rewriteContent(content []byte, tags structTags) ([]byte, error) {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, "", content, parser.ParseComments)
	if err != nil {
		return nil, fmt.Errorf("failed to parse generated go content: %w", err)
	}

	found := map[string]map[string]bool{}
	changed := false
	var rewriteErr error
	ast.Inspect(f, func(node ast.Node) bool {
		if rewriteErr != nil {
			return false
		}
		spec, ok := node.(*ast.TypeSpec)
		if !ok {
			return true
		}
		st, ok := spec.Type.(*ast.StructType)
		if !ok || tags[spec.Name.Name] == nil {
			return false
		}
		for _, field := range st.Fields.List {
			for _, name := range field.Names {
				fieldTags, ok := tags[spec.Name.Name][name.Name]
				if !ok {
					continue
				}
				if found[spec.Name.Name] == nil {
					found[spec.Name.Name] = map[string]bool{}
				}
				found[spec.Name.Name][name.Name] = true
				for _, tag := range fieldTags {
					fieldChanged, err := rewriteFieldTag(field, tag)
					if err != nil {
						rewriteErr = fmt.Errorf("%s.%s: %w", spec.Name.Name, name.Name, err)
						return false
					}
					changed = changed || fieldChanged
				}
			}
		}
		return false
	})
	if rewriteErr != nil {
		return nil, rewriteErr
	}
	for structName, fieldTags := range tags {
		for fieldName := range fieldTags {
			if !found[structName][fieldName] {
				return nil, fmt.Errorf("field %s.%s with struct tags not found in generated go content", structName, fieldName)
			}
		}
	}
	if !changed {
		return content, nil
	}

	var buf bytes.Buffer
	buf.WriteString(generatedComment)
	if err := format.Node(&buf, fset, f); err != nil {
		return nil, fmt.Errorf("failed to format go content: %w", err)
	}
	return buf.Bytes(), nil
}

// rewriteFieldTag updates or replaces struct tags of field by tag, reporting whether the struct tag is changed.
func rewriteFieldTag(field *ast.Field, tag fieldTag) (bool, error) {
	var old string
	if field.Tag != nil {
		old = field.Tag.Value
	}
	goTags, err := reflect.ParseAstStructTag(old)
	if err != nil {
		return false, fmt.Errorf("malformed struct tag %s generated: %w", old, err)
	}

	// Tags returns tags in random order, so select them in the order written in *.proto.
	for _, protoTag := range tag.tag.SelectedTags(tag.tag.OrderKeys()...) {
		goTag, _ := goTags.Get(protoTag.Key)
		goTag.Key = protoTag.Key
		if protoTag.Name != "" {
			goTag.Name = protoTag.Name
		}
		if tag.updateStrategy == pb.FieldTag_replace {
			goTag.Options = nil
		}
		goTag.AddOptions(protoTag.Options...)
		_ = goTags.Set(goTag)
	}

	// the order rule of struct tags is: protobuf, json, other tags in the same order written in *.proto.
	keys := []string{"protobuf", "json"}
	keys = append(keys, strings_.SliceTrim(goTags.OrderKeys(), "protobuf", "json")...)
	newTag := goTags.SelectAstString(keys...)
	if newTag == old {
		return false, nil
	}
	if field.Tag == nil {
		field.Tag = &ast.BasicLit{Kind: token.STRING}
	}
	field.Tag.Value = newTag
	return true, nil
}
